const stats = $input.first().json;
const msg = `Vendors: ${stats.totalVendors}
Services/Contracts: ${stats.totalServices}
Monthly Spend: Rs.${Math.round(stats.totalMonthlySpend).toLocaleString('en-IN')}
Yearly Spend: Rs.${Math.round(stats.totalYearlySpend).toLocaleString('en-IN')}
Expiring Soon (30d): ${stats.expiringSoon}
Expired: ${stats.expired}`;
return [{ json: { message: msg } }];

// Gmail hands from/to/cc over as objects: { value:[{address,name}], html, text }.
// String() on one yields "[object Object]", which silently defeats every address
// test and makes the workflow quietly process nothing. Always go through this.
const addr = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v.text === 'string') return v.text;
  if (Array.isArray(v.value)) return v.value.map(x => (x && x.address) || '').join(' ');
  return '';
};

// ---- RAC rental bills are NOT service contracts --------------------------
// Keep these two lists identical to the ones in "RAC Laptop Bill Auto-Capture"
// -> "Match RAC + Pick Bill". That workflow claims these mails; this one must
// skip them, or the same bill is booked twice.
const RAC_SENDERS = ['@racwg.com'];
const RAC_SUBJECT_KEYWORDS = ['laptop rent', 'laptop rental', 'rented laptop', 'rental invoice', 'rent invoice'];

const racFrom = addr($input.first().json.from);
const racHay = (racFrom + ' ' + String($input.first().json.subject || '')).toLowerCase();
const isRacBill = (RAC_SENDERS.length > 0 && RAC_SENDERS.some(a => racFrom.toLowerCase().includes(a.toLowerCase()))) ||
  /\brac\b/i.test(racHay) || RAC_SUBJECT_KEYWORDS.some(k => racHay.includes(k));
if (isRacBill) {
  return []; // handled by RAC Laptop Bill Auto-Capture instead
}

const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);
const pdfKey = keys.find(k => (binary[k].mimeType || '').includes('pdf') || (binary[k].fileName || '').toLowerCase().endsWith('.pdf'));
if (!pdfKey) {
  return []; // no PDF attachment on this email - skip it
}
return [{
  json: {
    from: addr(item.json.from), // was writing '[object Object]' into notes and ntfy
    subject: item.json.subject,
    originalFilename: binary[pdfKey].fileName || 'invoice.pdf'
  },
  binary: { pdf: binary[pdfKey] }
}];

const vendors = $('Get Existing Vendors').all().map(i => i.json);
const domains = $('Get Existing Domains').all().map(i => i.json);
const text = $('Extract PDF Text').first().json.text;
return [{ json: {
  text,
  existingVendors: vendors.map(v => v.name),
  existingDomains: domains.map(d => d.domain_name)
} }];

const parsed = $input.first().json;
let meta = { from: 'test', subject: 'test' };
try { meta = $('Normalize PDF Attachment').first().json; } catch (e) {}

let vendors = [];
try { vendors = $('Get Existing Vendors').all().map(i => i.json); } catch (e) {}
const exactMatch = vendors.find(v => v.name === parsed.vendor_name);

let vendorId;
if (exactMatch) {
  vendorId = exactMatch.id;
} else {
  const created = await this.helpers.httpRequest({
    method: 'POST', url: 'http://192.168.126.101:3000/api/vendors', json: true,
    body: { name: parsed.vendor_name, category: 'Auto-captured (Gmail)', email: parsed.vendor_email, phone: parsed.vendor_phone }
  });
  vendorId = created.id;
}

const service = await this.helpers.httpRequest({
  method: 'POST', url: 'http://192.168.126.101:3000/api/services', json: true,
  body: {
    vendor_id: vendorId,
    service_name: parsed.service_name,
    category: parsed.category,
    cost: parsed.cost,
    currency: parsed.currency,
    billing_cycle: parsed.billing_cycle,
    start_date: parsed.start_date,
    expiry_date: parsed.expiry_date,
    auto_renew: false,
    notes: `[Auto-captured from Gmail - please verify] Invoice#: ${parsed.invoice_number || 'N/A'} | ${parsed.notes || ''} | From email: ${meta.from || 'test'}`
  }
});

let pdfBinary = {};
try { pdfBinary = $('Normalize PDF Attachment').first().binary || {}; } catch (e) {}

return [{
  json: { ...parsed, vendorId, serviceId: service.id, sourceFrom: meta.from, sourceSubject: meta.subject },
  binary: pdfBinary
}];

const item = $input.first();
const parsed = item.json;

if (!parsed.seat_change_domain || !parsed.seat_change_count) {
  return [{ json: parsed, binary: item.binary }];
}

const domains = await this.helpers.httpRequest({ method: 'GET', url: 'http://192.168.126.101:3000/api/domains', json: true });
const match = domains.find(d => d.domain_name.toLowerCase() === String(parsed.seat_change_domain).toLowerCase());
if (!match) {
  return [{ json: { ...parsed, seatUpdateSkipped: 'domain not found in console: ' + parsed.seat_change_domain }, binary: item.binary }];
}

const delta = Number(parsed.seat_change_count);
const newTotal = (match.total_seats || 0) + delta;
const today = new Date().toISOString().slice(0, 10);
const noteAddition = ` | ${delta > 0 ? '+' : ''}${delta} seat(s) on ${today} via invoice ${parsed.invoice_number || 'N/A'} (auto-captured)`;

await this.helpers.httpRequest({
  method: 'PUT', url: `http://192.168.126.101:3000/api/domains/${match.id}`, json: true,
  body: {
    domain_name: match.domain_name,
    admin_email: match.admin_email,
    domain_type: match.domain_type,
    parent_domain_id: match.parent_domain_id,
    service_id: match.service_id,
    total_seats: newTotal,
    notes: (match.notes || '') + noteAddition
  }
});

// Keep the linked base contract's "(N Users)" label and "Total Users: N" note in sync too
if (match.service_id) {
  try {
    const services = await this.helpers.httpRequest({ method: 'GET', url: 'http://192.168.126.101:3000/api/services', json: true });
    const baseService = services.find(s => s.id === match.service_id);
    if (baseService) {
      const newServiceName = baseService.service_name.replace(/\(\s*\d+\s*Users?\s*\)/i, `(${newTotal} Users)`);
      const newServiceNotes = /Total Users:\s*\d+/i.test(baseService.notes || '')
        ? baseService.notes.replace(/Total Users:\s*\d+/i, `Total Users: ${newTotal}`)
        : baseService.notes;
      await this.helpers.httpRequest({
        method: 'PUT', url: `http://192.168.126.101:3000/api/services/${baseService.id}`, json: true,
        body: {
          vendor_id: baseService.vendor_id, service_name: newServiceName, category: baseService.category,
          cost: baseService.cost, currency: baseService.currency, billing_cycle: baseService.billing_cycle,
          start_date: baseService.start_date, expiry_date: baseService.expiry_date,
          auto_renew: !!baseService.auto_renew, notes: newServiceNotes
        }
      });
    }
  } catch (e) {}
}

return [{ json: { ...parsed, seatsUpdatedDomain: match.domain_name, seatsUpdatedNewTotal: newTotal }, binary: item.binary }];

const TAB = $('Resolve Tab Name').first().json.tab; // resolved from sheetId - survives a rename
// Column layout of the 'G Suite Main <count>' tab (HR rename it as the count moves,
// so the name is resolved from its sheetId upstream, never hardcoded):
//   A-D = regular user list  <- this workflow owns these four columns only
//   H-K = role / shared mailboxes, maintained by hand  <- never written to
const sheet = $input.first().json;
const grid = sheet.values || [];
const NL = String.fromCharCode(10);
const pad = (r, n) => (Array.isArray(r) ? r : []).concat(Array(n).fill('')).slice(0, n);
const trimTrailing = (rows) => {
  const c = rows.slice();
  while (c.length && c[c.length - 1].every(x => !x)) c.pop();
  return c;
};

// GUARD: if someone inserts or renames a column, our fixed A2:D200 range would
// silently write into the wrong place. Check the headers first and refuse to write.
const EXPECTED = ['First Name', 'Last Name', 'Email Address', 'Status'];
const actual = pad(grid[0], 4).map(c => String(c || '').trim());
if (EXPECTED.some((h, i) => h.toLowerCase() !== actual[i].toLowerCase())) {
  return [{ json: {
    okFlag: 0,
    problem: 'Column layout changed. Expected A1:D1 to be [' + EXPECTED.join(' | ') +
             '] but the sheet has [' + actual.join(' | ') + ']. Nothing was written.'
  }}];
}

// Role addresses live in column J of the H-K block; exclude them from A-D.
const roleEmails = new Set(
  grid.slice(1).map(r => String(pad(r, 11)[9] || '').trim().toLowerCase()).filter(Boolean)
);

// DRIFT CHECK: compare what is in A2:D200 right now against what this workflow
// wrote last time. Any difference means a person edited the sheet by hand.
const store = $getWorkflowStaticData('global');
const hadBaseline = Array.isArray(store.lastWritten);
const currentAD = trimTrailing(grid.slice(1, 200).map(r => pad(r, 4).map(c => String(c || '').trim())));
const drift = [];
if (hadBaseline) {
  const prev = store.lastWritten;
  const n = Math.max(prev.length, currentAD.length);
  for (let i = 0; i < n; i++) {
    const was = (prev[i] || ['', '', '', '']).join(' | ');
    const now = (currentAD[i] || ['', '', '', '']).join(' | ');
    if (was !== now) drift.push('row ' + (i + 2) + ': we wrote [' + was + '] but sheet had [' + now + ']');
  }
}

const mailboxes = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/mailboxes', json: true
});

function splitName(full) {
  const s = String(full || '').trim();
  if (!s) return ['', ''];
  const i = s.indexOf(' ');
  return i === -1 ? [s, ''] : [s.slice(0, i), s.slice(i + 1).trim()];
}

const rows = mailboxes
  .filter(m => String(m.email || '').toLowerCase().endsWith('@saleshandy.com'))
  .filter(m => !roleEmails.has(String(m.email).toLowerCase()))
  .map(m => {
    const [first, last] = splitName(m.current_user);
    return [first, last, m.email, m.status || ''];
  })
  .sort((a, b) =>
    a[0].toLowerCase().localeCompare(b[0].toLowerCase()) ||
    a[2].toLowerCase().localeCompare(b[2].toLowerCase())
  );

const MAX_ROWS = 199; // A2:D200
if (rows.length > MAX_ROWS) {
  return [{ json: { okFlag: 0, problem: rows.length + ' users no longer fit the A2:D200 range. Widen it before the next run. Nothing was written.' } }];
}
const values = rows.concat(Array.from({ length: MAX_ROWS - rows.length }, () => ['', '', '', '']));

// Status colours, matching what is already in the sheet by hand:
//   Active -> light green RGB(182,215,168), Inactive -> light red RGB(224,102,102)
const GREEN = { red: 182/255, green: 215/255, blue: 168/255 };
const RED   = { red: 224/255, green: 102/255, blue: 102/255 };
const WHITE = { red: 1, green: 1, blue: 1 };
const formatRows = values.map(r => {
  const status = String(r[3] || '').trim().toLowerCase();
  const bg = status === 'active' ? GREEN : (status ? RED : WHITE);
  return { values: [{ userEnteredFormat: { backgroundColor: bg } }] };
});

const prevWritten = JSON.stringify(store.lastWritten || []);
store.lastWritten = trimTrailing(values.map(r => r.map(c => String(c || '').trim())));
const contentChanged = JSON.stringify(store.lastWritten) !== prevWritten;

// Built here because n8n expressions cannot hold multi-statement logic.
let message = 'Wrote ' + rows.length + ' saleshandy.com users to ' + TAB + ' (columns A-D). ' +
              roleEmails.size + ' role addresses in H-K left untouched.';
if (drift.length) {
  message += NL + NL + 'WARNING - ' + drift.length +
             ' row(s) had been edited in the sheet by hand since the last sync.' +
             ' Those edits have now been overwritten:' + NL + drift.slice(0, 15).join(NL);
  if (drift.length > 15) message += NL + '...and ' + (drift.length - 15) + ' more';
}

return [{ json: {
  okFlag: 1,
  contentChanged,
  reportFlag: (contentChanged || drift.length > 0) ? 1 : 0,
  message,
  values, formatRows,
  userCount: rows.length,
  roleAddressesExcluded: roleEmails.size,
  driftCount: drift.length,
  drift: drift.slice(0, 15),
  baselineExisted: hadBaseline
} }];

// A tab's numeric sheetId survives a rename; its title does not. HR rename this
// tab whenever the licence count changes (G Suite Main 89 -> ...), and the old
// hardcoded name then failed every run with "Unable to parse range".
const SHEET_ID = 708600971;
const sheets = ($input.first().json.sheets || []).map(s => s.properties);
const hit = sheets.find(p => Number(p.sheetId) === SHEET_ID);
if (!hit) {
  throw new Error('Tab with sheetId ' + SHEET_ID + ' no longer exists in this spreadsheet. Tabs present: ' +
    sheets.map(p => p.title).join(', '));
}
return [{ json: { tab: hit.title } }];

// One workflow, three departments. The tabs are discovered upstream (HR rolls them
// over each year), so the department is read off each returned range rather than
// assumed from its position in the batchGet.
const DEPT_NAMES = { SH: 'Saleshandy', HA: 'HighAdvocacy', TI: 'TrulyInbox' };
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const NL = String.fromCharCode(10);
// Shared column layout across all three tabs:
// D=3 Department, F=5 Name, G=6 Designation, H=7 Joining Status, M=12 Mail ID Created
// Cells carry stray newlines and padding, so every read is trimmed.
const cell = (r, i) => String((r || [])[i] || '').trim();

const ranges = $input.first().json.valueRanges || [];

const joined = [];
const badFormat = [];
ranges.forEach(vr => {
  // vr.range looks like "'New Joiners- 2026 (SH)'!A1:S1100" - take the department from
  // the tab title itself so the order of the ranges cannot matter.
  const m = String(vr.range || '').match(/\(\s*(SH|HA|TI)\s*\)/i);
  if (!m) return;
  const key = m[1].toUpperCase();
  const rows = vr.values || [];
  rows.slice(1).forEach(r => {
    if (cell(r, 7) !== 'Joined') return;
    const mail = cell(r, 12);
    if (!mail) return;
    if (!EMAIL_RE.test(mail)) { badFormat.push(key + ': ' + mail); return; }
    joined.push({
      email: mail, name: cell(r, 5), designation: cell(r, 6),
      department: cell(r, 3), deptKey: key, deptName: DEPT_NAMES[key] || key
    });
  });
});

// The mail id's domain must already exist in the console, otherwise a typo or an
// untracked domain would quietly create a mailbox that belongs nowhere.
const domains = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/domains', json: true
});
const knownDomains = new Set(domains.map(x => String(x.domain_name).toLowerCase()));
const domainOf = (e) => String(e).split('@')[1].toLowerCase();
const valid = joined.filter(j => knownDomains.has(domainOf(j.email)));
const unknownDomain = joined
  .filter(j => !knownDomains.has(domainOf(j.email)))
  .map(j => j.deptKey + ': ' + j.email + ' (domain ' + domainOf(j.email) + ' not in console)');

// Add only people who show up after this workflow started watching. HR never flips a
// leaver's row back from "Joined", so without this baseline anyone deleted from the
// console by hand would be re-created as Active within 30 minutes, forever.
const store = $getWorkflowStaticData('global');
const firstRun = !Array.isArray(store.seenJoinerEmails);
const seen = new Set(store.seenJoinerEmails || []);

const existing = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/mailboxes', json: true
});
const existingEmails = new Set(existing.map(m => String(m.email).toLowerCase()));

const toAdd = firstRun ? [] : valid.filter(j =>
  !seen.has(j.email.toLowerCase()) && !existingEmails.has(j.email.toLowerCase())
);

for (const j of toAdd) {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://192.168.126.101:3000/api/mailboxes', json: true,
    body: {
      email: j.email,
      status: 'Active',
      current_user: j.name,
      purpose: [j.designation, j.department].filter(Boolean).join(' - '),
      notes: 'Auto-added from HR New Joiners sheet (' + j.deptKey + ' tab)'
    }
  });
}

store.seenJoinerEmails = [...new Set([...seen, ...valid.map(j => j.email.toLowerCase())])];

// Report each bad mail id once instead of every 30 minutes forever.
const problems = unknownDomain.concat(badFormat);
const reported = new Set(store.reportedProblems || []);
const newProblems = problems.filter(p => !reported.has(p));
store.reportedProblems = [...new Set([...reported, ...problems])];

const perDept = Object.keys(DEPT_NAMES).map(k =>
  k + '=' + joined.filter(j => j.deptKey === k).length
).join(' ');

let message = 'New joiners: added ' + toAdd.length + ' mailbox(es). Joined rows seen: ' + perDept + '.';
if (toAdd.length) {
  message += NL + toAdd.map(j => j.deptKey + ': ' + j.email + '  (' + j.name + ')').join(NL);
}
if (newProblems.length) {
  message += NL + NL + 'Check these mail IDs - not added:' + NL + newProblems.join(NL);
}

return [{ json: {
  baselinedOnFirstRun: firstRun,
  totalJoinedInSheets: joined.length,
  perDepartment: perDept,
  tabsRead: ranges.map(v => String(v.range || '').split('!')[0]),
  newlyAdded: toAdd.length,
  added: toAdd.map(j => j.deptKey + ': ' + j.email),
  skippedUnknownDomain: unknownDomain,
  skippedBadFormat: badFormat,
  alertFlag: (toAdd.length + newProblems.length) > 0 ? 1 : 0,
  message
} }];

// HR creates a fresh tab every year ('New Joiners- 2026 (SH)' -> '...2027 (SH)').
// Hardcoding the year means that the day HR moves on, this workflow keeps reading the
// dead tab, finds nothing new, and fails SILENTLY. So discover the tabs instead, and
// read every matching year - which also covers the changeover period when entries
// land in both the old and the new tab.
const sheets = ($input.first().json.sheets || []).map(s => s.properties.title);

const DEPTS = ['SH', 'HA', 'TI'];
const MIN_YEAR = 2026;

const picked = [];
for (const title of sheets) {
  const t = title.toLowerCase();
  if (!t.includes('new joiner')) continue;
  const year = (title.match(/(20\d{2})/) || [])[1];
  if (!year || Number(year) < MIN_YEAR) continue;
  const dept = DEPTS.find(d => new RegExp('\(\s*' + d + '\s*\)', 'i').test(title));
  if (!dept) continue;
  picked.push({ title, dept, year: Number(year) });
}
picked.sort((a, b) => a.dept.localeCompare(b.dept) || a.year - b.year);

// Nothing matching at all means the naming changed in a way this pattern does not
// cover. Say so loudly rather than quietly adding nobody.
if (!picked.length) {
  return [{ json: {
    ok: 0,
    problem: 'No joiner tabs matched. Looked for a title containing "new joiner", a year >= ' +
             MIN_YEAR + ', and (SH)/(HA)/(TI). Tabs present: ' + sheets.join(', ')
  }}];
}

const rangesQuery = picked
  .map(p => 'ranges=' + encodeURIComponent(p.title + '!A1:S1100'))
  .join('&');

return [{ json: { ok: 1, rangesQuery, picked, tabList: picked.map(p => p.dept + ':' + p.title) } }];

const TAB = $('Resolve Tab Name').first().json.tab; // resolved from sheetId - survives a rename
// 'G Suite Krishna <count>' layout (name resolved from sheetId upstream):  A=Sr #  B=Email Address  C=Status  D=Purpose  E=Current User
// A user row is one where A is a number and B is an email. Anything else (the domain
// list block, the stray red row underneath) is not ours and is never touched.
const grid = $input.first().json.values || [];
const NL = String.fromCharCode(10);
const cell = (r, i) => String((r || [])[i] || '').trim();

const userRows = [];
grid.forEach((r, i) => {
  const sr = cell(r, 0), email = cell(r, 1);
  if (/^\d+$/.test(sr) && email.includes('@')) {
    userRows.push({ row: i + 1, sr: Number(sr), email: email.toLowerCase(),
                    status: cell(r, 2), purpose: cell(r, 3), user: cell(r, 4) });
  }
});
if (!userRows.length) {
  return [{ json: { addCount: 0, alertFlag: 1, message: 'Krishna sheet: no user rows found - layout may have changed. Nothing written.' } }];
}
const lastRow = Math.max(...userRows.map(u => u.row));
const lastSr  = Math.max(...userRows.map(u => u.sr));
const inSheet = new Set(userRows.map(u => u.email));

// DRIFT: compare every existing user row against the snapshot from the last run.
// Keyed by email, not row number, so inserting rows does not raise false alarms.
const store = $getWorkflowStaticData('global');
const prev = store.snapshot || null;
const drift = [];
if (prev) {
  const now = {};
  userRows.forEach(u => { now[u.email] = [String(u.sr), u.status, u.purpose, u.user].join(' | '); });
  Object.keys(prev).forEach(e => {
    if (!(e in now)) drift.push('REMOVED  ' + e + '  was [' + prev[e] + ']');
    else if (prev[e] !== now[e]) drift.push('CHANGED  ' + e + NL + '   was [' + prev[e] + ']' + NL + '   now [' + now[e] + ']');
  });
}

// Console mailboxes for the krishnabusinesshub tenant = its primary domain + secondaries.
const domains = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/domains', json: true
});
const primary = domains.find(d => String(d.domain_name).toLowerCase() === 'krishnabusinesshub.com');
const tenant = new Set([String(primary.domain_name).toLowerCase()].concat(
  domains.filter(d => d.parent_domain_id === primary.id).map(d => String(d.domain_name).toLowerCase())
));
const mailboxes = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/mailboxes', json: true
});
const missing = mailboxes
  .filter(m => tenant.has(String(m.email).split('@')[1].toLowerCase()))
  .filter(m => !inSheet.has(String(m.email).toLowerCase()))
  .sort((a, b) => String(a.email).localeCompare(String(b.email)));

// New rows are appended directly under the last user row, so the domain-list block
// and anything else below it shifts down intact rather than being overwritten.
const newRows = missing.map((m, k) => [lastSr + 1 + k, m.email, m.status || 'Active', m.purpose || '', m.current_user || '']);

let message = 'Krishna sheet: ' + newRows.length + ' new row(s) appended. Sheet has ' + userRows.length + ' users, console has ' +
              mailboxes.filter(m => tenant.has(String(m.email).split('@')[1].toLowerCase())).length + '.';
if (newRows.length) message += NL + newRows.map(r => r[0] + '. ' + r[1]).join(NL);
if (drift.length) {
  message += NL + NL + 'WARNING - ' + drift.length + ' existing row(s) were edited by hand since the last run:' + NL + drift.slice(0, 12).join(NL);
  if (drift.length > 12) message += NL + '...and ' + (drift.length - 12) + ' more';
}

// Snapshot AFTER computing drift, including the rows about to be appended.
const snap = {};
userRows.forEach(u => { snap[u.email] = [String(u.sr), u.status, u.purpose, u.user].join(' | '); });
newRows.forEach(r => { snap[String(r[1]).toLowerCase()] = [r[0], r[2], r[3], r[4]].join(' | '); });
store.snapshot = snap;

return [{ json: {
  addCount: newRows.length,
  driftCount: drift.length,
  alertFlag: (newRows.length + drift.length) > 0 ? 1 : 0,
  insertStartIndex: lastRow,
  insertEndIndex: lastRow + newRows.length,
  writeRange: TAB + '!A' + (lastRow + 1) + ':E' + (lastRow + newRows.length),
  newRows, message
} }];

// A tab's numeric sheetId survives a rename; its title does not. HR rename this
// tab whenever the licence count changes, and a hardcoded name then fails every
// run with "Unable to parse range" - which is exactly what killed the master
// user sync for days before anyone noticed.
const SHEET_ID = 860200999;
const sheets = ($input.first().json.sheets || []).map(s => s.properties);
const hit = sheets.find(p => Number(p.sheetId) === SHEET_ID);
if (!hit) {
  throw new Error('Tab with sheetId ' + SHEET_ID + ' no longer exists in this spreadsheet. Tabs present: ' +
    sheets.map(p => p.title).join(', '));
}
return [{ json: { tab: hit.title } }];

// 'TrulyInbox GW' layout:  A=Sr #  B=First Name  C=Last Name  D=Email Address
// A user row is one where A is a number and D is an email. Row 2 (the admin,
// vatsal@trulyinbox.com) is highlighted green by hand, so this workflow is
// append-only: existing rows are never rewritten and never re-sorted, which would
// move that highlight onto the wrong person.
const grid = $input.first().json.values || [];
const NL = String.fromCharCode(10);
const cell = (r, i) => String((r || [])[i] || '').trim();

const userRows = [];
grid.forEach((r, i) => {
  const sr = cell(r, 0), email = cell(r, 3);
  if (/^\d+$/.test(sr) && email.includes('@')) {
    userRows.push({ row: i + 1, sr: Number(sr), email: email.toLowerCase(),
                    first: cell(r, 1), last: cell(r, 2) });
  }
});
if (!userRows.length) {
  return [{ json: { addCount: 0, alertFlag: 1, message: 'TrulyInbox GW sheet: no user rows found - layout may have changed. Nothing written.' } }];
}
const lastRow = Math.max(...userRows.map(u => u.row));
const lastSr  = Math.max(...userRows.map(u => u.sr));
const inSheet = new Set(userRows.map(u => u.email));

// DRIFT, keyed by email rather than row number so appends do not raise false alarms.
const store = $getWorkflowStaticData('global');
const prev = store.snapshot || null;
const drift = [];
if (prev) {
  const now = {};
  userRows.forEach(u => { now[u.email] = [String(u.sr), u.first, u.last].join(' | '); });
  Object.keys(prev).forEach(e => {
    if (!(e in now)) drift.push('REMOVED  ' + e + '  was [' + prev[e] + ']');
    else if (prev[e] !== now[e]) drift.push('CHANGED  ' + e + NL + '   was [' + prev[e] + ']' + NL + '   now [' + now[e] + ']');
  });
}

const mailboxes = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/mailboxes', json: true
});
const tenant = mailboxes.filter(m => String(m.email).toLowerCase().endsWith('@trulyinbox.com'));
const inConsole = new Set(tenant.map(m => String(m.email).toLowerCase()));

function splitName(full) {
  const s = String(full || '').trim();
  if (!s) return ['', ''];
  const i = s.indexOf(' ');
  return i === -1 ? [s, ''] : [s.slice(0, i), s.slice(i + 1).trim()];
}

const missing = tenant
  .filter(m => !inSheet.has(String(m.email).toLowerCase()))
  .sort((a, b) => String(a.email).localeCompare(String(b.email)));
const newRows = missing.map((m, k) => {
  const [first, last] = splitName(m.current_user);
  return [lastSr + 1 + k, first, last, m.email];
});

// Rows present in the sheet but not in the console - not touched, only reported.
const sheetOnly = userRows.filter(u => !inConsole.has(u.email)).map(u => u.email);

let message = 'TrulyInbox GW sheet: ' + newRows.length + ' new row(s) appended. Sheet has ' +
              userRows.length + ' users, console has ' + tenant.length + '.';
if (newRows.length) message += NL + newRows.map(r => r[0] + '. ' + r[3]).join(NL);
if (sheetOnly.length) message += NL + NL + 'In the sheet but NOT in the IT console (left alone):' + NL + sheetOnly.join(NL);
if (drift.length) {
  message += NL + NL + 'WARNING - ' + drift.length + ' existing row(s) were edited by hand since the last run:' + NL + drift.slice(0, 12).join(NL);
  if (drift.length > 12) message += NL + '...and ' + (drift.length - 12) + ' more';
}

const snap = {};
userRows.forEach(u => { snap[u.email] = [String(u.sr), u.first, u.last].join(' | '); });
newRows.forEach(r => { snap[String(r[3]).toLowerCase()] = [r[0], r[1], r[2]].join(' | '); });
store.snapshot = snap;

return [{ json: {
  addCount: newRows.length,
  driftCount: drift.length,
  sheetOnlyCount: sheetOnly.length,
  alertFlag: (newRows.length + drift.length + sheetOnly.length) > 0 ? 1 : 0,
  insertStartIndex: lastRow,
  insertEndIndex: lastRow + newRows.length,
  writeRange: 'TrulyInbox GW!A' + (lastRow + 1) + ':D' + (lastRow + newRows.length),
  newRows, message
} }];

// 'Exit-<year>' layout:  A=Month B=Name C=Resignation/Termination D=Reporting Manager
//                        E=Department F=Exit Date G=Notice H=Damage I=Device J=Mail ID
// Tabs are discovered upstream (HR rolls Exit-2026 -> Exit-2027) and every matching
// year is read, so the changeover needs no remapping.
// The sheet is filled bottom-to-top, so row position is deliberately ignored.
const NL = String.fromCharCode(10);
const cell = (r, i) => String((r || [])[i] || '').trim();

const MONTHS = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
// Handles '3rd September 2026', '27th Feb 2026' and typos like '20th Feb2026'.
function parseExitDate(raw) {
  const s = String(raw || '').toLowerCase().replace(/(\d)(st|nd|rd|th)/g, '$1').replace(/([a-z])(\d)/g, '$1 $2');
  const m = s.match(/(\d{1,2})\s+([a-z]+)\s+(\d{4})/);
  if (!m) return null;
  const mi = MONTHS.indexOf(m[2].slice(0, 3));
  if (mi === -1) return null;
  return new Date(Date.UTC(Number(m[3]), mi, Number(m[1]), 12, 0, 0));
}

// Exit dates are Indian calendar dates and this runs at 00:00 IST, which is
// 18:30 UTC the day before - so a UTC-derived "today" is a day behind on every
// scheduled run, and everyone gets removed a day late. Shift into IST first.
const IST_OFFSET = 5.5 * 3600000;
const istNow = new Date(Date.now() + IST_OFFSET);
const today = new Date(Date.UTC(istNow.getUTCFullYear(), istNow.getUTCMonth(), istNow.getUTCDate(), 12, 0, 0));
const DAY = 86400000;

const mailboxes = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/mailboxes', json: true
});
const byEmail = new Map(mailboxes.map(m => [String(m.email).toLowerCase(), m]));

const ranges = $input.first().json.valueRanges || [];
const due = [], notYet = [], unparsable = [], suspiciouslyOld = [], alreadyGone = [];

ranges.forEach(vr => {
  (vr.values || []).slice(1).forEach(r => {
    const email = cell(r, 9).toLowerCase();
    if (!email || !email.includes('@')) return;
    const name = cell(r, 1), rawDate = cell(r, 5);
    const exit = parseExitDate(rawDate);
    if (!exit) { unparsable.push(name + ' [' + rawDate + '] ' + email); return; }

    // Removed ON the exit date, not the day after. The date is still honoured,
    // so a row filled in ahead of time waits for the day rather than acting now.
    const removeOn = exit;
    if (today < removeOn) { notYet.push(name + ' -> ' + removeOn.toISOString().slice(0, 10)); return; }
    if (!byEmail.has(email)) { alreadyGone.push(email); return; }

    // A mistyped year ('25th August 2025' where the Month column says Aug'26) would
    // otherwise read as long overdue and delete instantly. Report instead.
    if (today.getTime() - exit.getTime() > 90 * DAY) {
      suspiciouslyOld.push(name + ' [' + rawDate + '] ' + email + ' - exit date is >90 days old, check the year');
      return;
    }
    due.push({ email, name, id: byEmail.get(email).id, exit: exit.toISOString().slice(0, 10) });
  });
});

const removed = [], failed = [];
for (const d of due) {
  try {
    await this.helpers.httpRequest({
      method: 'DELETE', url: 'http://192.168.126.101:3000/api/mailboxes/' + d.id, json: true
    });
    removed.push(d);
  } catch (e) {
    failed.push(d.email + ' - ' + (e.message || 'delete failed'));
  }
}

let message = 'Exit sync: removed ' + removed.length + ' mailbox(es) from the IT console.';
if (removed.length) message += NL + removed.map(d => d.email + '  (' + d.name + ', exit ' + d.exit + ')').join(NL);
if (failed.length) message += NL + NL + 'FAILED to delete:' + NL + failed.join(NL);
if (suspiciouslyOld.length) message += NL + NL + 'Not touched - exit date looks wrong:' + NL + suspiciouslyOld.join(NL);
if (unparsable.length) message += NL + NL + 'Not touched - could not read the exit date:' + NL + unparsable.join(NL);

return [{ json: {
  ranAsOf: today.toISOString().slice(0, 10),
  tabsRead: ranges.map(v => String(v.range || '').split('!')[0]),
  removedCount: removed.length,
  removed: removed.map(d => d.email),
  pending: notYet,
  alreadyGoneCount: alreadyGone.length,
  suspiciouslyOld, unparsable, failed,
  alertFlag: (removed.length + failed.length + suspiciouslyOld.length + unparsable.length) > 0 ? 1 : 0,
  message
} }];

// Same reasoning as the joiner workflow: HR rolls the tab over each year
// ('Exit-2026' -> 'Exit-2027'). Discover them so nothing is missed at the changeover.
// The pattern is strict on purpose - it must not pick up 'Exit Oct-Dec'25' or 'Old Exit',
// which have a different shape.
const sheets = ($input.first().json.sheets || []).map(s => s.properties.title);
const MIN_YEAR = 2026;

const picked = sheets
  .map(t => ({ title: t, m: t.match(/^\s*exit\s*-\s*(20\d{2})\s*$/i) }))
  .filter(x => x.m && Number(x.m[1]) >= MIN_YEAR)
  .map(x => ({ title: x.title, year: Number(x.m[1]) }))
  .sort((a, b) => a.year - b.year);

if (!picked.length) {
  return [{ json: {
    ok: 0,
    problem: 'No exit tab matched the pattern Exit-<year> with year >= ' + MIN_YEAR +
             '. Tabs present: ' + sheets.join(', ')
  }}];
}

const rangesQuery = picked
  .map(p => 'ranges=' + encodeURIComponent(p.title + '!A1:J200'))
  .join('&');

return [{ json: { ok: 1, rangesQuery, tabList: picked.map(p => p.title) } }];

const TAB = $('Resolve Tab Name').first().json.tab; // resolved from sheetId - survives a rename
// 'SaleshandySolutions-<count>' layout (name resolved from sheetId upstream): A=Sr # B=Email C=Status D=Purpose E=Current User F=Password
// Column F holds passwords - never read, never written, never logged.
// A user row is one where A is a number and B is an email, so the legend/domain block
// further down the tab is ignored.
//
// This is the only TWO-WAY sync. Direction is decided by a three-way compare against a
// snapshot of the last synced state, so "sheet and console differ" resolves into "which
// side actually changed" instead of one side blindly winning.
const grid = $input.first().json.values || [];
const NL = String.fromCharCode(10);
const cell = (r, i) => String((r || [])[i] || '').trim();
const FIELDS = ['status', 'purpose', 'user'];

const sheetRows = [];
grid.forEach((r, i) => {
  const sr = cell(r, 0), email = cell(r, 1);
  if (/^\d+$/.test(sr) && email.includes('@')) {
    sheetRows.push({ row: i + 1, sr: Number(sr), email: email, key: email.toLowerCase(),
                     status: cell(r, 2), purpose: cell(r, 3), user: cell(r, 4) });
  }
});
if (!sheetRows.length) {
  return [{ json: { editCount: 0, appendCount: 0, alertFlag: 1,
    message: 'Solutions sync: no user rows found - layout may have changed. Nothing written.' } }];
}
const lastRow = Math.max.apply(null, sheetRows.map(u => u.row));
const lastSr = Math.max.apply(null, sheetRows.map(u => u.sr));
const bySheet = new Map(sheetRows.map(u => [u.key, u]));

// Console side = the Solutions tenant: its primary domain plus every secondary under it.
const domains = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/domains', json: true
});
const primary = domains.find(d => String(d.domain_name).toLowerCase() === 'saleshandysolutions.com');
if (!primary) {
  return [{ json: { editCount: 0, appendCount: 0, alertFlag: 1,
    message: 'Solutions sync: saleshandysolutions.com is not in the console. Nothing written.' } }];
}
const tenant = new Set([String(primary.domain_name).toLowerCase()].concat(
  domains.filter(d => d.parent_domain_id === primary.id).map(d => String(d.domain_name).toLowerCase())));

const mailboxes = await this.helpers.httpRequest({
  method: 'GET', url: 'http://192.168.126.101:3000/api/mailboxes', json: true
});
const consoleRows = mailboxes.filter(m => tenant.has(String(m.email).split('@')[1].toLowerCase()));
const byConsole = new Map(consoleRows.map(m => [String(m.email).toLowerCase(), m]));

const store = $getWorkflowStaticData('global');
const base = store.snapshot || null;
const norm = (st, pu, us) => ({ status: st || '', purpose: pu || '', user: us || '' });
const same = (a, b) => !!a && !!b && FIELDS.every(f => (a[f] || '') === (b[f] || ''));

const toConsole = [], toSheet = [], conflicts = [];
const addToConsole = [], addToSheet = [];
const sheetOnlyGone = [], consoleOnlyGone = [];

const allKeys = new Set();
bySheet.forEach((v, k) => allKeys.add(k));
byConsole.forEach((v, k) => allKeys.add(k));

allKeys.forEach(key => {
  const s = bySheet.get(key);
  const c = byConsole.get(key);
  const sn = s ? norm(s.status, s.purpose, s.user) : null;
  const cn = c ? norm(c.status, c.purpose, c.current_user) : null;
  const b = base ? base[key] : undefined;

  if (s && !c) {
    if (b) consoleOnlyGone.push(s.email);
    else addToConsole.push(s);
    return;
  }
  if (c && !s) {
    if (b) sheetOnlyGone.push(c.email);
    else addToSheet.push(c);
    return;
  }
  if (same(sn, cn)) return;

  if (!b) { conflicts.push(key + ' - differs but there is no baseline yet, left alone'); return; }
  const sheetMoved = !same(sn, b);
  const consoleMoved = !same(cn, b);
  if (sheetMoved && consoleMoved) {
    conflicts.push(key + NL + '   sheet   [' + FIELDS.map(f => sn[f]).join(' | ') + ']' +
                         NL + '   console [' + FIELDS.map(f => cn[f]).join(' | ') + ']');
  } else if (sheetMoved) {
    toConsole.push({ s: s, c: c });
  } else if (consoleMoved) {
    toSheet.push({ s: s, c: c });
  }
});

// Console-side writes happen here; sheet writes are done by the nodes downstream.
const doneConsole = [];
for (const t of toConsole) {
  await this.helpers.httpRequest({
    method: 'PUT', url: 'http://192.168.126.101:3000/api/mailboxes/' + t.c.id, json: true,
    body: { email: t.c.email, status: t.s.status || 'Active', purpose: t.s.purpose,
            current_user: t.s.user, notes: t.c.notes }
  });
  doneConsole.push(t.c.email);
}
for (const s of addToConsole) {
  await this.helpers.httpRequest({
    method: 'POST', url: 'http://192.168.126.101:3000/api/mailboxes', json: true,
    body: { email: s.email, status: s.status || 'Active', purpose: s.purpose,
            current_user: s.user, notes: 'Added from the ' + TAB + ' sheet' }
  });
  doneConsole.push(s.email + ' (new)');
}

const sheetEdits = toSheet.map(t => ({
  range: TAB + '!C' + t.s.row + ':E' + t.s.row,
  values: [[t.c.status || '', t.c.purpose || '', t.c.current_user || '']]
}));
const newRows = addToSheet.map((m, k) => [lastSr + 1 + k, m.email, m.status || 'Active',
                                          m.purpose || '', m.current_user || '']);

// The baseline records the state both sides are converging on, so the next run can
// still tell which side moved.
const gone = {};
sheetOnlyGone.forEach(e => { gone[e.toLowerCase()] = 1; });
consoleOnlyGone.forEach(e => { gone[e.toLowerCase()] = 1; });
const snap = {};
allKeys.forEach(key => {
  if (gone[key]) return;
  const s = bySheet.get(key), c = byConsole.get(key);
  if (toConsole.find(t => t.s.key === key)) snap[key] = norm(s.status, s.purpose, s.user);
  else if (toSheet.find(t => t.s.key === key)) snap[key] = norm(c.status, c.purpose, c.current_user);
  else if (s) snap[key] = norm(s.status, s.purpose, s.user);
  else if (c) snap[key] = norm(c.status, c.purpose, c.current_user);
});
addToSheet.forEach(m => { snap[String(m.email).toLowerCase()] = norm(m.status, m.purpose, m.current_user); });
store.snapshot = snap;

let message = 'Solutions sync: sheet ' + sheetRows.length + ' rows, console ' + consoleRows.length + ' mailboxes.';
if (doneConsole.length) message += NL + NL + 'Sheet -> console (' + doneConsole.length + '):' + NL + doneConsole.join(NL);
if (sheetEdits.length) message += NL + NL + 'Console -> sheet (' + sheetEdits.length + '):' + NL + toSheet.map(t => t.c.email).join(NL);
if (newRows.length) message += NL + NL + 'Appended to sheet (' + newRows.length + '):' + NL + newRows.map(r => r[1]).join(NL);
if (conflicts.length) message += NL + NL + 'CONFLICT - both sides changed since the last sync, nothing applied:' + NL + conflicts.join(NL);
if (sheetOnlyGone.length) message += NL + NL + 'Gone from the sheet, still in the console (NOT deleted):' + NL + sheetOnlyGone.join(NL);
if (consoleOnlyGone.length) message += NL + NL + 'Gone from the console, still in the sheet (NOT deleted):' + NL + consoleOnlyGone.join(NL);

return [{ json: {
  firstRun: !base,
  editCount: sheetEdits.length,
  appendCount: newRows.length,
  consoleWrites: doneConsole.length,
  conflicts: conflicts,
  sheetOnlyGone: sheetOnlyGone,
  consoleOnlyGone: consoleOnlyGone,
  sheetEdits: sheetEdits,
  newRows: newRows,
  insertStartIndex: lastRow,
  insertEndIndex: lastRow + newRows.length,
  writeRange: TAB + '!A' + (lastRow + 1) + ':E' + (lastRow + newRows.length),
  alertFlag: (doneConsole.length + sheetEdits.length + newRows.length + conflicts.length +
              sheetOnlyGone.length + consoleOnlyGone.length) > 0 ? 1 : 0,
  message: message
} }];

// A tab's numeric sheetId survives a rename; its title does not. HR rename this
// tab whenever the licence count changes (SaleshandySolutions-10 -> ...), and the old
// hardcoded name then failed every run with "Unable to parse range".
const SHEET_ID = 623354432;
const sheets = ($input.first().json.sheets || []).map(s => s.properties);
const hit = sheets.find(p => Number(p.sheetId) === SHEET_ID);
if (!hit) {
  throw new Error('Tab with sheetId ' + SHEET_ID + ' no longer exists in this spreadsheet. Tabs present: ' +
    sheets.map(p => p.title).join(', '));
}
return [{ json: { tab: hit.title } }];

// Manual-run only. Mirrors a real RAC e-invoice mail (body table + attachment) so
// a manual execution exercises every node after "Match RAC + Pick Bill".
const body = [
  'Dear Sir,',
  'Greetings from RAC IT SOLUTIONS PVT LTD !!!',
  'We are sending the copy of E-Invoices raised on your esteemed organization for our rental charges.',
  '',
  'Inv No | Inv Date | Location | Date From | Date To | Net Amt | GST | Total Amt',
  'AMD/26-27/MANUALTEST | 19-08-2026 | Gujarat | 18-08-2026 | 17-09-2026 | 3200.00 | 576.00 | 3776.00',
  '',
  'Please make a note of below email id for sending payment details/payment advises.',
  'accountsahmd@racwg.com'
].join('\n');

const esc = s => s.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
const lines = body.split('\n').map((l, i) => 'BT /F1 9 Tf 30 ' + (780 - i * 13) + ' Td (' + esc(l) + ') Tj ET').join('\n');
const objs = [
  '<</Type/Catalog/Pages 2 0 R>>',
  '<</Type/Pages/Kids[3 0 R]/Count 1>>',
  '<</Type/Page/Parent 2 0 R/MediaBox[0 0 595 842]/Resources<</Font<</F1 4 0 R>>>>/Contents 5 0 R>>',
  '<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>',
  '<</Length ' + lines.length + '>>\nstream\n' + lines + '\nendstream'
];
let pdf = '%PDF-1.4\n';
const offsets = [];
objs.forEach((o, i) => { offsets.push(pdf.length); pdf += (i + 1) + ' 0 obj\n' + o + '\nendobj\n'; });
const xref = pdf.length;
pdf += 'xref\n0 ' + (objs.length + 1) + '\n0000000000 65535 f \n' +
  offsets.map(o => String(o).padStart(10, '0') + ' 00000 n \n').join('') +
  'trailer\n<</Size ' + (objs.length + 1) + '/Root 1 0 R>>\nstartxref\n' + xref + '\n%%EOF';

return [{
  json: {
    // Same shape Gmail actually sends - an object, not a string. A fixture
    // that hands over a plain string tests a case that never happens.
    from: { value: [{ address: 'accounts@racwg.com', name: 'Parshuram Kuwlekar' }],
            text: '"Parshuram Kuwlekar" <accounts@racwg.com>' },
    subject: 'E-INVOICE-IKIGAI INFOTECH LLP -AMD/26-27/MANUALTEST',
    text: body,
    snippet: body.slice(0, 200)
  },
  binary: {
    bill: {
      data: Buffer.from(pdf, 'latin1').toString('base64'),
      mimeType: 'application/pdf',
      fileName: 'AMD-26-27-MANUALTEST.pdf'
    }
  }
}];

// ---- RAC matching config -------------------------------------------------
// RAC IT Solutions Pvt Ltd bill from several mailboxes on one domain
// (accounts@, accountsahmd@, receivables3@, hobilling@, salesahmd4@ ...), so the
// domain is what to match on - not any single address.
// The SAME list exists in "Gmail Invoice Auto-Capture" -> "Normalize PDF
// Attachment", which uses it to SKIP these mails. Change both together, or one
// RAC bill lands in the console twice: once as a rental payment and once as a
// service contract.
const SENDERS = ['@racwg.com'];
const SUBJECT_KEYWORDS = ['laptop rent', 'laptop rental', 'rented laptop', 'rental invoice', 'rent invoice'];

// Gmail hands from/to/cc over as objects: { value:[{address,name}], html, text }.
// String() on one yields "[object Object]", which silently defeats every address
// test and makes the workflow quietly process nothing. Always go through this.
const addr = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v.text === 'string') return v.text;
  if (Array.isArray(v.value)) return v.value.map(x => (x && x.address) || '').join(' ');
  return '';
};

const item = $input.first();
const from = addr(item.json.from);
const subject = String(item.json.subject || '');
const haystack = (from + ' ' + subject).toLowerCase();

const senderHit = SENDERS.some(a => from.toLowerCase().includes(a.toLowerCase()));
const keywordHit = /\brac\b/i.test(haystack) || SUBJECT_KEYWORDS.some(k => haystack.includes(k));

if (!senderHit && !keywordHit) {
  return []; // not a RAC bill - stop here, nothing downstream runs
}

// RAC also send statements, reminders and replies on the same thread. Only a mail
// that actually announces an invoice should book money.
const looksLikeInvoice = /invoice|bill|rental charges/i.test(subject) ||
  /e-?invoice|rental charges|invoices raised/i.test(String(item.json.text || item.json.snippet || ''));
if (senderHit && !looksLikeInvoice) {
  return [];
}

// The email body carries RAC's invoice table, so it is worth keeping even when a
// PDF is attached - the two corroborate each other.
let emailText = String(item.json.text || '');
if (!emailText && item.json.html) {
  emailText = String(item.json.html)
    .replace(/<\s*(br|\/tr|\/p|\/div)[^>]*>/gi, '\n')
    .replace(/<\s*\/?\s*t[dh][^>]*>/gi, ' | ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}
emailText = ('Subject: ' + subject + '\n\n' + emailText).slice(0, 12000);

// Prefer a PDF; fall back to a photo/scan of the bill.
const binary = item.binary || {};
const keys = Object.keys(binary);
const isPdf = k => (binary[k].mimeType || '').includes('pdf') || (binary[k].fileName || '').toLowerCase().endsWith('.pdf');
const isImage = k => (binary[k].mimeType || '').startsWith('image/') ||
  /\.(jpe?g|png|webp|heic)$/i.test(binary[k].fileName || '');

// Gmail inlines a signature block and names those parts image001.png,
// image002.png ... A real attachment keeps its own filename. RAC's reply to our
// payment proof carries their signature and nothing else, and its subject still
// says E-INVOICE - without this it would be parsed as a bill.
const looksInlined = k => /^image\d{3}\.(png|jpe?g|gif|webp)$/i.test(binary[k].fileName || '');
const realImages = keys.filter(k => isImage(k) && !looksInlined(k));

// Their bills are always a PDF (e-invoice with an IRN). A properly-named image is
// still accepted in case a scan ever arrives; a mail carrying only inline parts
// is not a bill.
const pick = keys.find(isPdf) || realImages[0];
if (!pick) {
  return []; // no bill attached - just a reply, an acknowledgement, or a signature
}

return [{
  json: {
    from,
    subject,
    emailText,
    originalFilename: binary[pick].fileName || 'rac-bill',
    mimeType: binary[pick].mimeType || '',
    isPdfFlag: isPdf(pick) ? 1 : 0
  },
  binary: { bill: binary[pick] }
}];

const src = $('Match RAC + Pick Bill').first();
const meta = src.json;

// Existing laptops go into the prompt so a machine already on record comes back
// under its own asset_name instead of being duplicated under a new one.
let existingAssets = [];
try {
  const rentals = await this.helpers.httpRequest({ method: 'GET', url: 'http://192.168.126.101:3000/api/rentals', json: true });
  existingAssets = (rentals || []).map(r => ({ asset_name: r.asset_name, serial_no: r.serial_no, model: r.model }));
} catch (e) {
  existingAssets = [];
}

const body = { existingAssets, emailText: meta.emailText || '' };

if (meta.isPdfFlag === 1) {
  body.text = $('Extract PDF Text').first().json.text || '';
  // A scanned PDF yields no text - the email body alone still carries RAC's
  // invoice table, so that is enough to go on.
  if (!body.text.trim() && !body.emailText.trim()) {
    throw new Error('Neither the PDF nor the email body had any readable text.');
  }
} else {
  let buf;
  try {
    buf = await this.helpers.getBinaryDataBuffer(0, 'bill');
  } catch (e) {
    buf = Buffer.from(src.binary.bill.data, 'base64');
  }
  body.imageBase64 = buf.toString('base64');
  body.imageMime = meta.mimeType || 'image/jpeg';
}

return [{ json: body }];

// Indian calendar date. `new Date().toISOString()` is the UTC date, which is
// still yesterday until 05:30 IST.
const istToday = () => new Date(Date.now() + 5.5 * 3600000).toISOString().slice(0, 10);
const parsed = $input.first().json;
const meta = $('Match RAC + Pick Bill').first().json;
const API = 'http://192.168.126.101:3000';

// One RAC email can carry several e-invoices - their body lists one table row
// each. Older single-invoice shapes are still accepted.
let invoices = Array.isArray(parsed.invoices) ? parsed.invoices.slice() : [];
if (!invoices.length && typeof parsed.amount === 'number') {
  invoices = [{
    invoice_number: parsed.invoice_number, invoice_date: parsed.invoice_date,
    period_label: parsed.period_label, amount: parsed.amount
  }];
}
invoices = invoices.filter(i => i && typeof i.amount === 'number' && i.amount > 0);
if (!invoices.length) {
  throw new Error('Parser returned no usable invoice: ' + JSON.stringify(parsed).slice(0, 300));
}

const existing = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/rentals', json: true });
const payments = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/rental-payments', json: true });
const norm = s => String(s || '').replace(/[^a-z0-9]/gi, '').toLowerCase();

// Reconcile the machines listed on the bill. RAC usually bill a lump sum per
// location with no per-machine breakdown, in which case this loop does nothing.
const added = [], updated = [];
for (const l of (Array.isArray(parsed.laptops) ? parsed.laptops : [])) {
  if (!l || !l.asset_name) continue;
  // Serial wins over name: a tag can be re-used on a replacement, a serial cannot.
  const match = existing.find(r => l.serial_no && norm(r.serial_no) && norm(r.serial_no) === norm(l.serial_no)) ||
                existing.find(r => norm(r.asset_name) === norm(l.asset_name));

  if (match) {
    const wantsRent = l.monthly_rent != null && Number(l.monthly_rent) !== Number(match.monthly_rent);
    const wantsSerial = l.serial_no && !match.serial_no;
    const wantsModel = l.model && !match.model;
    if (!wantsRent && !wantsSerial && !wantsModel) continue;
    // PUT is a full replace on this API - every field has to be echoed back.
    await this.helpers.httpRequest({
      method: 'PUT', url: API + '/api/rentals/' + match.id, json: true,
      body: {
        vendor_name: match.vendor_name || 'RAC', asset_name: match.asset_name,
        model: wantsModel ? l.model : match.model,
        serial_no: wantsSerial ? l.serial_no : match.serial_no,
        assigned_to: match.assigned_to,
        monthly_rent: wantsRent ? l.monthly_rent : match.monthly_rent,
        rent_start: match.rent_start, rent_end: match.rent_end,
        status: match.status || 'On Rent', gmail_link: match.gmail_link, notes: match.notes
      }
    });
    updated.push(match.asset_name + (wantsRent ? ' (rent ' + match.monthly_rent + ' -> ' + l.monthly_rent + ')' : ''));
  } else {
    const inv0 = invoices[0] || {};
    await this.helpers.httpRequest({
      method: 'POST', url: API + '/api/rentals', json: true,
      body: {
        vendor_name: 'RAC', asset_name: l.asset_name, model: l.model, serial_no: l.serial_no,
        monthly_rent: l.monthly_rent,
        // The billed period start is when the machine actually went on rent, which
        // the invoice date only approximates.
        rent_start: inv0.period_from || inv0.invoice_date || null,
        status: 'On Rent',
        notes: '[Auto-added from RAC bill ' + (inv0.invoice_number || 'n/a') + ' - please verify]' +
               (l.asset_no ? ' RAC asset no ' + l.asset_no + '.' : '')
      }
    });
    added.push(l.asset_name + (l.serial_no ? ' / SN ' + l.serial_no : ''));
  }
}

const out = [];
const skipped = [];
let billBinary = {};
try { billBinary = $('Match RAC + Pick Bill').first().binary || {}; } catch (e) {}

for (const inv of invoices) {
  const invoiceNo = String(inv.invoice_number || '').trim();
  // Same invoice number seen before => Gmail re-delivered a mail already booked,
  // or RAC re-sent it as a reminder. Never book the same invoice twice.
  if (invoiceNo && payments.some(p => (p.invoice_no || '').trim().toLowerCase() === invoiceNo.toLowerCase())) {
    skipped.push(invoiceNo);
    continue;
  }

  const period = inv.period_label ||
    (inv.period_from && inv.period_to ? inv.period_from + ' to ' + inv.period_to : null);

  const bits = [];
  if (inv.location) bits.push('Location: ' + inv.location);
  if (inv.net_amount != null) bits.push('Net ' + inv.net_amount);
  if (inv.gst_amount != null) bits.push('GST ' + inv.gst_amount);
  if (inv.po_number) bits.push('PO ' + inv.po_number);
  if (parsed.billed_to) bits.push('Billed to: ' + parsed.billed_to);

  // status Pending: this is an invoice asking to be paid, not a receipt.
  const payment = await this.helpers.httpRequest({
    method: 'POST', url: API + '/api/rental-payments', json: true,
    body: {
      vendor_name: 'RAC', asset_id: null, amount: inv.amount,
      payment_date: inv.invoice_date || istToday(),
      period_label: period, payment_method: parsed.payment_method || null,
      invoice_no: invoiceNo || null, status: 'Pending',
      due_date: inv.due_date || null,
      notes: '[Auto-captured from Gmail - NOT PAID YET, verify] ' + bits.join(' | ') +
             (bits.length ? ' | ' : '') + (parsed.notes || '') + ' | From: ' + (meta.from || 'manual test')
    }
  });

  out.push({
    json: {
      paymentId: payment.id, amount: inv.amount, invoice_no: invoiceNo || null,
      period_label: period, location: inv.location || null, due_date: inv.due_date || null,
      payment_date: inv.invoice_date || istToday(),
      billedTo: parsed.billed_to || null,
      invoicesOnMail: invoices.length, skippedDuplicates: skipped,
      laptopsAdded: added, laptopsUpdated: updated,
      sourceFrom: meta.from, sourceSubject: meta.subject
    },
    binary: billBinary
  });
}

// Everything on this mail was already booked - stop, no second NAS copy, no alert.
return out;

// Runs once for every invoice booked off this mail, and reports them together.
const booked = $('Record Payment + Sync Laptops').all().map(i => i.json);
const first = booked[0];
const API = 'http://192.168.126.101:3000';

const payments = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/rental-payments', json: true });
const rentals = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/rentals', json: true });

const onRent = rentals.filter(r => (r.status || 'On Rent') === 'On Rent');
const monthlyExpected = onRent.reduce((s, r) => s + (Number(r.monthly_rent) || 0), 0);

const bookedIds = new Set(booked.map(b => b.paymentId));
const isPaid = p => (p.status || 'Pending') === 'Paid';
// What actually left the bank. RAC deduct 2% TDS u/s 194I, so a paid row is
// routinely lower than the invoice it settles.
const outflow = p => Number(p.paid_amount != null ? p.paid_amount : p.amount) || 0;

// "Already paid" must mean money that actually left - Pending rows are what we owe.
const paid = payments.filter(isPaid);
const totalPaid = paid.reduce((s, p) => s + outflow(p), 0);
const outstanding = payments.filter(p => !isPaid(p));
const outstandingTotal = outstanding.reduce((s, p) => s + (Number(p.amount) || 0), 0);

// Indian financial year: 1 Apr - 31 Mar.
const d = new Date(first.payment_date);
const fyStartYear = d.getMonth() + 1 >= 4 ? d.getFullYear() : d.getFullYear() - 1;
const fyStart = fyStartYear + '-04-01', fyEnd = (fyStartYear + 1) + '-03-31';
const inFy = p => p.payment_date >= fyStart && p.payment_date <= fyEnd;
const fyPaidRows = paid.filter(inFy);
const fyPaid = fyPaidRows.reduce((s, p) => s + outflow(p), 0);
const fyBilled = payments.filter(inFy).reduce((s, p) => s + (Number(p.amount) || 0), 0);

// Newest by the date the money went out, not by the bill's own date.
const previous = paid.filter(p => !bookedIds.has(p.id))
  .sort((a, b) => String(b.paid_on || b.payment_date).localeCompare(String(a.paid_on || a.payment_date)))[0] || null;

const newTotal = booked.reduce((s, b) => s + (Number(b.amount) || 0), 0);

return [{ json: {
  invoices: booked.map(b => ({
    invoice_no: b.invoice_no, amount: b.amount, period_label: b.period_label,
    location: b.location, due_date: b.due_date
  })),
  newCount: booked.length,
  newTotal,
  billedTo: first.billedTo,
  payment_date: first.payment_date,
  skippedDuplicates: first.skippedDuplicates || [],
  laptopsAdded: first.laptopsAdded || [],
  laptopsUpdated: first.laptopsUpdated || [],
  laptopsOnRent: onRent.length,
  monthlyExpected,
  totalPaid, paidCount: paid.length,
  outstandingTotal, outstandingCount: outstanding.length,
  fyLabel: 'FY' + String(fyStartYear).slice(2) + '-' + String(fyStartYear + 1).slice(2),
  fyPaid, fyPaidCount: fyPaidRows.length, fyBilled,
  previousAmount: previous ? outflow(previous) : null,
  previousDate: previous ? (previous.paid_on || previous.payment_date) : null,
  previousPeriod: previous ? previous.period_label : null,
  sourceFrom: first.sourceFrom
} }];

