parameters.jsCode:
// Manual-run only. Mirrors the reply we send RAC with the bank screenshot on it.
const png = '';
return [{
  json: {
    to: { value: [{ address: 'accounts@racwg.com', name: 'Parshuram Kuwlekar' }],
          text: '"Parshuram Kuwlekar" <accounts@racwg.com>' },
    cc: 'Ravip@saleshandy.com, accountsahmd@racwg.com',
    subject: 'Re: E-INVOICE-IKIGAI INFOTECH LLP -AMD/26-27/99999',
    text: 'Hi Parshuram,\n\nThe payment for invoice number AMD/26-27/99999 has been processed. Please find the payment proof attached.\n\nThanks,\nPriyanshu',
    snippet: 'The payment for invoice number AMD/26-27/99999 has been processed.'
  },
  binary: {
    proof: { data: png, mimeType: 'image/png', fileName: 'payment-proof.png' },
    sig: { data: 'iVBORw0KGgo=', mimeType: 'image/png', fileName: 'signature.png', fileSize: '1.2 kB' }
  }
}];

// ---- config, kept identical to the bill workflow ------------------------
const RECIPIENTS = ['@racwg.com'];

// Gmail hands from/to/cc over as objects: { value:[{address,name}], html, text }.
// String() on one yields "[object Object]", which silently defeats every address
// test and makes the workflow quietly process nothing. Always go through this.
const addr = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v.text === 'string') return v.text;
  if (Array.isArray(v.value)) return v.value.map(x => (x && x.address) || '').join(' ');
  return '';
};

const item = $input.first();
const to = addr(item.json.to) + ' ' + addr(item.json.cc);
const subject = String(item.json.subject || '');
const bodyText = String(item.json.text || item.json.snippet || '');

if (!RECIPIENTS.some(a => to.toLowerCase().includes(a.toLowerCase()))) {
  return []; // not addressed to RAC
}

// Only a mail that actually claims to carry a payment proof should settle money.
if (!/payment|paid|proof|remitt|utr|neft|imps|rtgs/i.test(subject + ' ' + bodyText)) {
  return [];
}

// RAC invoice numbers look like AMD/26-27/00669. The subject of a reply carries
// it, which is the only reliable way to know which bill is being settled.
const invRe = /\b[A-Z]{2,4}\/\d{2}-\d{2}\/\d{3,8}\b/g;
const invoiceHints = Array.from(new Set(
  ((subject + ' ' + bodyText).match(invRe) || []).map(x => x.trim())
));

// The signature logo is an attachment too. Prefer a PDF; among images take the
// largest and ignore anything small enough to be a logo.
const binary = item.binary || {};
const approxBytes = (b) => {
  const m = String(b.fileSize || '').match(/([\d.]+)\s*(k|m)?b/i);
  if (m) {
    const n = parseFloat(m[1]);
    const unit = (m[2] || '').toLowerCase();
    return Math.round(n * (unit === 'm' ? 1048576 : unit === 'k' ? 1024 : 1));
  }
  return b.data ? Math.round(String(b.data).length * 0.75) : 0;
};

const keys = Object.keys(binary);
const isPdf = k => (binary[k].mimeType || '').includes('pdf') || (binary[k].fileName || '').toLowerCase().endsWith('.pdf');
const isImage = k => (binary[k].mimeType || '').startsWith('image/') ||
  /\.(jpe?g|png|webp|heic)$/i.test(binary[k].fileName || '');

// Gmail inlines the signature block and names those parts image001.png,
// image002.png ... A real attachment keeps its own filename. Observed live: one
// mail carried image001..image007 plus the screenshot, and the biggest signature
// part was within 2KB of the proof - so size alone is not a safe signal.
const looksInlined = k => /^image\d{3}\.(png|jpe?g|gif|webp)$/i.test(binary[k].fileName || '');

let pick = keys.find(isPdf);
if (!pick) {
  const rank = k => (looksInlined(k) ? 0 : 1);
  const imgs = keys.filter(isImage).sort((a, b) =>
    (rank(b) - rank(a)) || (approxBytes(binary[b]) - approxBytes(binary[a])));
  // Among equally-ranked images the largest wins; tiny ones are only dropped
  // when there is something else to compare against, so a small but genuine
  // screenshot is never thrown away.
  pick = imgs.length > 1
    ? (imgs.filter(k => approxBytes(binary[k]) >= 8000)[0] || imgs[0])
    : imgs[0];
}
if (!pick) {
  return []; // nothing that could be a proof
}

let emailText = String(item.json.text || '');
if (!emailText && item.json.html) {
  emailText = String(item.json.html)
    .replace(/<\s*(br|\/tr|\/p|\/div)[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}
emailText = ('Subject: ' + subject + '\n\n' + emailText).slice(0, 8000);

return [{
  json: {
    to, subject, emailText, invoiceHints,
    originalFilename: binary[pick].fileName || 'payment-proof',
    mimeType: binary[pick].mimeType || '',
    isPdfFlag: isPdf(pick) ? 1 : 0
  },
  binary: { proof: binary[pick] }
}];

const src = $('Match Proof + Pick File').first();
const meta = src.json;

// Only unpaid bills are candidates - a proof cannot settle something already settled.
let openInvoices = [];
try {
  const payments = await this.helpers.httpRequest({ method: 'GET', url: 'http://192.168.126.101:3000/api/rental-payments', json: true });
  openInvoices = (payments || [])
    .filter(p => (p.status || 'Pending') !== 'Paid' && p.invoice_no)
    .map(p => ({ invoice_no: p.invoice_no, amount: p.amount, period_label: p.period_label }));
} catch (e) {
  openInvoices = [];
}

const body = { openInvoices, emailText: meta.emailText || '' };

if (meta.isPdfFlag === 1) {
  body.text = $('Extract Proof Text').first().json.text || '';
} else {
  let buf;
  try {
    buf = await this.helpers.getBinaryDataBuffer(0, 'proof');
  } catch (e) {
    buf = Buffer.from(src.binary.proof.data, 'base64');
  }
  body.imageBase64 = buf.toString('base64');
  body.imageMime = meta.mimeType || 'image/png';
}

return [{ json: body }];

const parsed = $input.first().json;
const meta = $('Match Proof + Pick File').first().json;
const API = 'http://192.168.126.101:3000';

if (parsed.looks_like_payment_proof === false) {
  throw new Error('The attached file is not a payment proof (parser said so). Nothing was changed. File: ' + (meta.originalFilename || '?'));
}
if (!(Number(parsed.amount) > 0)) {
  throw new Error('No amount could be read off the proof. Nothing was changed. File: ' + (meta.originalFilename || '?'));
}

const norm = s => String(s || '').replace(/\s+/g, '').toLowerCase();
const candidates = [parsed.invoice_number].concat(meta.invoiceHints || []).filter(Boolean);
if (!candidates.length) {
  throw new Error('Could not tell which invoice this proof settles - no invoice number in the proof, subject or body.');
}

const payments = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/rental-payments', json: true });
const wanted = new Set(candidates.map(norm));
const matches = payments.filter(p => p.invoice_no && wanted.has(norm(p.invoice_no)));

// Never guess. Settling the wrong row is worse than settling none.
if (matches.length === 0) {
  throw new Error('No console bill matches ' + candidates.join(' / ') + '. Book the bill first, then re-send the proof.');
}
if (matches.length > 1) {
  throw new Error('More than one bill matches ' + candidates.join(' / ') + ' - refusing to guess. Fix the duplicates in the console.');
}

const pmt = matches[0];
const amount = Number(parsed.amount);

// Settled already with the same figures? Then the only thing that might still
// be missing is the file itself - a bill marked Paid by hand has the numbers but
// no screenshot. Bail out only when there is genuinely nothing left to do.
const settledSame = (pmt.status || 'Pending') === 'Paid' &&
  Number(pmt.paid_amount != null ? pmt.paid_amount : pmt.amount) === amount &&
  (!parsed.paid_on || pmt.paid_on === parsed.paid_on);

let fileAlreadyOnRow = false;
try {
  const atts = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/attachments', json: true });
  fileAlreadyOnRow = (atts || []).some(a =>
    a.entity_type === 'rental_payment' && Number(a.entity_id) === Number(pmt.id) &&
    a.original_filename === meta.originalFilename);
} catch (e) { fileAlreadyOnRow = false; }

if (settledSame && fileAlreadyOnRow) {
  return []; // same mail delivered again - nothing to add
}

const shortfall = Math.round((Number(pmt.amount) - amount) * 100) / 100;
const gapNote = shortfall > 0
  ? '. Short of the invoice by ' + shortfall + ' (expected: 2% TDS u/s 194I).'
  : shortfall < 0
    ? '. OVERPAID the invoice by ' + Math.abs(shortfall) + ' - check this.'
    : '. Matches the invoice exactly.';
const bits = [];
if (parsed.method) bits.push(parsed.method);
if (parsed.bank_ref) bits.push('bank ref ' + parsed.bank_ref);
if (parsed.reference_no) bits.push('reference no ' + parsed.reference_no);
if (parsed.beneficiary_account) bits.push('to A/C ' + parsed.beneficiary_account);

// PUT is a full replace - echo every field back or it is written as NULL.
if (!settledSame) await this.helpers.httpRequest({
  method: 'PUT', url: API + '/api/rental-payments/' + pmt.id, json: true,
  body: {
    vendor_name: pmt.vendor_name || 'RAC',
    asset_id: pmt.asset_id,
    amount: pmt.amount,
    payment_date: pmt.payment_date,
    period_label: pmt.period_label,
    payment_method: parsed.method || pmt.payment_method,
    invoice_no: pmt.invoice_no,
    gmail_link: pmt.gmail_link,
    status: 'Paid',
    due_date: pmt.due_date,
    paid_on: parsed.paid_on || pmt.paid_on,
    paid_amount: amount,
    notes: (pmt.notes || '') + ' | AUTO-SETTLED from payment proof: ' + bits.join(', ') +
           gapNote + ' ' + (parsed.notes || '')
  }
});

let proofBinary = {};
try { proofBinary = $('Match Proof + Pick File').first().binary || {}; } catch (e) {}

return [{
  json: {
    paymentId: pmt.id, invoice_no: pmt.invoice_no, billed: Number(pmt.amount),
    paidAmount: amount, paidOn: parsed.paid_on || pmt.paid_on,
    method: parsed.method || null, bankRef: parsed.bank_ref || null,
    referenceNo: parsed.reference_no || null, shortfall,
    dueDate: pmt.due_date || null, periodLabel: pmt.period_label || null,
    wasAlreadyPaid: (pmt.status || 'Pending') === 'Paid',
    proofFile: meta.originalFilename, subject: meta.subject
  },
  binary: proofBinary
}];

// Indian calendar date. `new Date().toISOString()` is the UTC date, which is
// still yesterday until 05:30 IST.
const istToday = () => new Date(Date.now() + 5.5 * 3600000).toISOString().slice(0, 10);
const s = $('Settle Payment').first().json;
const API = 'http://192.168.126.101:3000';

const payments = await this.helpers.httpRequest({ method: 'GET', url: API + '/api/rental-payments', json: true });
const isPaid = p => (p.status || 'Pending') === 'Paid';
const outflow = p => Number(p.paid_amount != null ? p.paid_amount : p.amount) || 0;

const paid = payments.filter(isPaid);
const outstanding = payments.filter(p => !isPaid(p));

const d = new Date(s.paidOn || istToday());
const fyStartYear = d.getMonth() + 1 >= 4 ? d.getFullYear() : d.getFullYear() - 1;
const fyStart = fyStartYear + '-04-01', fyEnd = (fyStartYear + 1) + '-03-31';
const inFy = p => (p.paid_on || p.payment_date) >= fyStart && (p.paid_on || p.payment_date) <= fyEnd;

return [{ json: {
  ...s,
  totalPaid: paid.reduce((t, p) => t + outflow(p), 0),
  paidCount: paid.length,
  outstandingTotal: outstanding.reduce((t, p) => t + (Number(p.amount) || 0), 0),
  outstandingCount: outstanding.length,
  fyLabel: 'FY' + String(fyStartYear).slice(2) + '-' + String(fyStartYear + 1).slice(2),
  fyPaid: paid.filter(inFy).reduce((t, p) => t + outflow(p), 0)
} }];

