  else if (s.shortfall < 0) { L.push('PAID MORE than billed by ' + rs(Math.abs(s.shortfall)) + ' - check this.'); }
  const ref = [s.method, s.bankRef ? 'ref ' + s.bankRef : null, s.referenceNo ? 'no ' + s.referenceNo : null].filter(Boolean);
  if (ref.length) { L.push(ref.join('   ')); }
