const NL = String.fromCharCode(10);
const all = ['Discover + Backup Host', 'Backup Omada + BioMax', 'Build RESTORE.sh', 'Upload + Verify + Prune']
  .map(n => { try { return $(n).first().json.stdout || ''; } catch (e) { return ''; } }).join(NL);

const verified  = all.includes('---ALL-VERIFIED---');
const vmSkipped = all.includes('---VM-SKIPPED---');
const problems  = all.split(NL).filter(l => /^(WARN|ERROR|MISMATCH)/.test(l));
const captured  = all.split(NL).filter(l => /^OK  /.test(l)).length;
const coverage  = (all.match(/COVERAGE [^\n]*/) || [''])[0];
const discovered= (all.match(/discovered: [^\n]*/) || [''])[0];
const size      = (all.match(/size=(\S+)/) || [])[1] || 'unknown';
const nasdir    = (all.match(/nasdir=(\S+)/) || [])[1] || 'n/a';
const date      = new Date(Date.now() + 5.5 * 3600000).toISOString().slice(0, 10);

let msg = (verified ? 'Backup OK' : 'Backup FAILED') + ' - IKI-MAC-27 ' + date;
msg += NL + 'NAS: ' + nasdir;
msg += NL + 'size: ' + size + '  archives: ' + captured;
if (discovered) msg += NL + discovered;
if (coverage)   msg += NL + coverage;
if (vmSkipped)  msg += NL + NL + 'NOTE: .180 unreachable - Omada/BioMax NOT in this backup.';
if (problems.length) msg += NL + NL + 'Problems:' + NL + problems.slice(0, 20).join(NL);
if (!verified)  msg += NL + NL + 'Old backups NOT pruned - previous backup still on the NAS.';

return [{ json: { verified, vmSkipped, captured, coverage, size, nasdir, problems, message: msg } }];

// Same IST-not-UTC rule as the daily job.
const istNow = new Date(Date.now() + 5.5 * 3600000);
const date  = istNow.toISOString().slice(0, 10);
const stamp = istNow.toISOString().slice(0, 19).replace('T', ' ') + ' IST';

return [{ json: {
  date, stamp,
  SYSTEM:   'IKI-MAC-27',
  NAS_HOST: 'truenas_admin@192.168.126.21',
  // Image backups live in their own folder so the daily job's YYYY-MM-DD
  // prune can never reach them.
  NAS_DIR:  '/mnt/ikigai-local/share1/Backups/IKI-MAC-27/vm-image',
  VM_IP:    '192.168.126.180',
  VM_UUID:  '662D77D5-33A5-43F1-8AF0-37AC6E02723D',
  BUNDLE:   '/Users/admin/Desktop/OmadaVM-Backups/OmadaVM-backup-20260716.utm',
  TMP:      '/Users/admin/backup-tmp',
  ZIP:      'vm-image-' + date + '.zip'
} }];

const NL = String.fromCharCode(10);
const text = $input.all().map(i => i.json.stdout || '').join(NL);
const p = $('Build Paths').first().json;
const prev = [
  $('Safe Stop VM').first().json.stdout || '',
  $('Zip VM Image').first().json.stdout || '',
  $('Restart VM').first().json.stdout || ''
].join(NL);
const all = prev + NL + text;

const verified  = all.includes('---IMAGE-VERIFIED---');
const vmBack    = all.includes('---VM-RESTARTED---') && /OK  VM back|VM already down/.test(all);
const problems  = all.split(NL).filter(l => /^(ERROR|WARN)/.test(l));
const sizeLine  = (all.match(/OK  zip (\S+)/) || [])[1] || 'unknown';

let msg = (verified ? 'VM Image Backup OK' : 'VM Image Backup FAILED') + ' - ' + p.date;
msg += NL + 'NAS: ' + p.NAS_DIR + '/' + p.ZIP;
msg += NL + 'size: ' + sizeLine;
msg += NL + 'VM restarted: ' + (vmBack ? 'yes' : 'NO - CHECK OMADA/BIOMAX');
if (problems.length) msg += NL + NL + problems.join(NL);
if (!verified) msg += NL + NL + 'Previous image on the NAS was NOT deleted.';

return [{ json: { ...p, verified, vmBack, problems, message: msg,
  alertOk: verified && vmBack } }];
